  const vanX=w*.51,vanY=h*.52;ctx.lineWidth=1;for(let i=-8;i<=8;i++){const endX=vanX+i*w*.13;ctx.beginPath();ctx.moveTo(vanX+i*2,vanY);ctx.lineTo(endX,h);ctx.strokeStyle=i%2?'#c3a9a522':'#ffb98920';ctx.stroke();}for(let j=1;j<9;j++){let t=j/9,y=vanY+(h-vanY)*t*t;ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(w,y);ctx.strokeStyle='#c2b9cb'+(j<4?'16':'20');ctx.stroke();}
  for(let i=0;i<8;i++){const x=((i*197+31)%w),y=h*(.57+(i%3)*.035);ctx.fillStyle=i%2?'#d8a277':'#24283b';ctx.beginPath();ctx.ellipse(x,y,10+i%3*3,3,0,0,Math.PI*2);ctx.fill();}
