  $('helpBtn').addEventListener('click',()=>openModal('controls'));$('modalClose').addEventListener('click',closeModal);modal.addEventListener('click',e=>{if(e.target===modal)closeModal();});confirm.addEventListener('click',()=>{const fn=modalAction;closeModal();fn&&fn();});document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal();});
  document.querySelectorAll('.nav-item').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('.nav-item').forEach(n=>n.classList.remove('active'));b.classList.add('active');if(b.dataset.tab!=='arena')openModal(b.dataset.tab);}));
