(() => {
  'use strict';
  const canvas=document.getElementById('gameCanvas'),ctx=canvas.getContext('2d'),$=id=>document.getElementById(id);
  const state={race:'Saiyan',level:8,xp:2450,xpNext:3200,hp:100,ki:76,transformed:false,wave:2,enemiesDefeated:0,wins:1,kiUses:2,coins:1250,toastTimer:0,lastTime:0,time:0,shake:0,attacks:[],particles:[],floating:[],keys:new Set(),player:{x:.28,y:.78,attack:0,invuln:0,support:0},enemy:null,sound:true};
  const races={Saiyan:{avatar:'悟',color:'#ffb454',bonus:'+15% poder de ataque',name:'KAI',portrait:'悟'},Namekiano:{avatar:'ナ',color:'#72de95',bonus:'+20% resistencia',name:'NARU',portrait:'ナ'},Androide:{avatar:'∞',color:'#72caff',bonus:'+25% regeneración de Ki',name:'UNIT-08',portrait:'∞'},Majin:{avatar:'魔',color:'#d39bf5',bonus:'+18% velocidad de Ki',name:'MIRA',portrait:'魔'}};
  const enemyTypes=[{name:'ANDROID 17',cls:'ÉLITE · ANDROIDE',mark:'17',color:'#9eb6c7',hp:4},{name:'FRIEZA SOLDIER',cls:'GUERRERO · FREEZER',mark:'F',color:'#d3a6e2',hp:3},{name:'SAIBAMAN',cls:'INVASOR · SAIYANO',mark:'S',color:'#90dc78',hp:3},{name:'CELL JR.',cls:'ÉLITE · BIO-ANDROID',mark:'C',color:'#8f9ff2',hp:4},{name:'MAJIN BOO',cls:'JEFE · DEMONIO',mark:'B',color:'#ee9ab9',hp:8}];
  const rand=(a,b)=>a+Math.random()*(b-a),clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
  function resize(){const r=canvas.getBoundingClientRect(),d=Math.min(devicePixelRatio||1,2);canvas.width=Math.round(r.width*d);canvas.height=Math.round(r.height*d);ctx.setTransform(d,0,0,d,0,0);}window.addEventListener('resize',resize);resize();
  function makeEnemy(boss=false){const t=boss?enemyTypes[4]:enemyTypes[Math.floor(Math.random()*4)];state.enemy={...t,x:.76,y:.73,hp:t.hp,maxHp:t.hp,attackClock:rand(.4,1.7),hit:0,boss,phase:rand(0,6)};$('enemyName').textContent=t.name;$('enemyClass').textContent=t.cls;$('enemyPortrait').textContent=t.mark;$('enemyPortrait').style.color=t.color;$('enemyBar').style.width='100%';}makeEnemy();
  function setToast(text,duration=2200){const el=$('toast');el.textContent=text;el.classList.add('show');clearTimeout(setToast.timer);setToast.timer=setTimeout(()=>el.classList.remove('show'),duration);}
  function combatToast(text,sub=''){const el=$('arenaToast');el.innerHTML=`<span>✦</span> ${text}${sub?`<small>${sub}</small>`:''}`;el.classList.add('show');clearTimeout(combatToast.timer);combatToast.timer=setTimeout(()=>el.classList.remove('show'),2000);}
  function syncHUD(){const r=races[state.race];$('pilotName').textContent=state.race.toUpperCase();$('levelSmall').textContent=String(state.level).padStart(2,'0');$('heroHudName').textContent=r.name;$('heroPortrait').textContent=r.portrait;$('pilotAvatar').querySelector('span').textContent=r.avatar;$('heroPortrait').style.background=`linear-gradient(145deg,${r.color},#52364b)`;$('hpBar').style.width=`${state.hp}%`;$('hpText').textContent=`${Math.round(state.hp)}%`;$('kiBar').style.width=`${state.ki}%`;$('kiText').textContent=`${Math.round(state.ki)}%`;$('formTag').textContent=state.transformed?'SUPER':'BASE';$('formTag').style.color=state.transformed?'#ffe87d':'';$('xpLabel').textContent=`${state.xp.toLocaleString('es')} / ${state.xpNext.toLocaleString('es')}`;$('xpBar').style.width=`${state.xp/state.xpNext*100}%`;$('currency').textContent=state.coins.toLocaleString('es');$('waveNum').textContent=String(state.wave).padStart(2,'0');$('raceBonus').innerHTML=`<span>✦</span> ${r.bonus} <b>${state.race.toUpperCase()}</b>`;document.querySelectorAll('.race-option').forEach(b=>b.classList.toggle('selected',b.dataset.race===state.race));$('winProgress').style.width=`${Math.min(100,state.wins/3*100)}%`;$('wins').textContent=`${Math.min(3,state.wins)}/3`;$('kiProgress').style.width=`${Math.min(100,state.kiUses/5*100)}%`;$('kiUses').textContent=`${Math.min(5,state.kiUses)}/5`;$('eventProgress').textContent=`${Math.min(8,state.enemiesDefeated+2)} / 8`;$('eventBar').style.width=`${Math.min(100,(state.enemiesDefeated+2)/8*100)}%`;}
  function particle(x,y,color,count=9,power=1){for(let i=0;i<count;i++)state.particles.push({x,y,vx:rand(-1,1)*power,vy:rand(-1,1)*power,life:rand(.25,.65),max:.65,size:rand(1,4),color});}
  function floatText(x,y,text,color='#fff0c1'){state.floating.push({x,y,text,color,life:.8});}
  function action(kind='melee'){if(!state.enemy)return;const p=state.player,e=state.enemy,rect=canvas.getBoundingClientRect(),near=Math.abs(p.x-e.x)<.22;if(kind==='melee'){p.attack=.22;state.shake=.13;if(near)damageEnemy(state.transformed?2:1,e.x*rect.width,e.y*rect.height,'#ffb45c');else state.attacks.push({x:p.x+.06,y:p.y-.09,target:e.x,kind:'dash',life:.24,color:'#ffe3a0'});return;}if(kind==='blast'){if(state.ki<12){setToast('¡Necesitas más Ki para usar esa técnica!');return;}state.ki-=12;state.kiUses++;state.attacks.push({x:p.x+.055,y:p.y-.1,target:e.x,kind:'blast',life:.48,color:races[state.race].color});particle(p.x*rect.width,p.y*rect.height,races[state.race].color,8,2);syncHUD();}else if(kind==='special'){if(state.ki<35){setToast('Necesitas 35% de Ki para Kamehameha');return;}state.ki-=35;state.kiUses++;state.attacks.push({x:p.x+.06,y:p.y-.09,target:e.x,kind:'beam',life:.7,color:'#79d9ff'});state.shake=.22;syncHUD();}else if(kind==='support'){if(p.support>0){setToast('Krilin todavía está preparando su siguiente técnica');return;}p.support=12;state.attacks.push({x:p.x,y:p.y-.2,target:e.x,kind:'support',life:.55,color:'#fff08b'});setToast('¡Krilin usa Disparo Solar!');}}
